#!/usr/bin/env escript
-module(greet).
-export([main/1]).

main(_) ->
    io:format("~s~n", [greet(en)]),
    io:format("~s~n", [greet(es)]),
    io:format("~s~n", [greet(fr)]).

greet(en) -> "Hello";
greet(es) -> "Hola";
greet(_) -> "Hi".

#!/usr/bin/env escript
-module(sign).
-export([main/1]).

main(_) ->
    io:format("~p ~p ~p~n", [sign(-5), sign(0), sign(7)]).

sign(N) when N < 0 -> negative;
sign(0) -> zero;
sign(N) when N > 0 -> positive.

